class Solution:
    def findAnagrams(self, s: str, p: str) -> List[int]:
        m, res = len(p), []
        need, win = Counter(p), Counter()
        for r, ch in enumerate(s):
            win[ch] += 1                # 右边进
            if r >= m:
                left = s[r - m]
                win[left] -= 1          # 左边出
                if win[left] == 0:
                    del win[left]
            if win == need:
                res.append(r - m + 1)
        return res

class Solution:
    def findAnagrams(self, s: str, p: str) -> List[int]:
        need, win, k, res = Counter(p), Counter(), len(p), []
        for i, c in enumerate(s):
            win[c] += 1
            if i >= k:
                win[s[i - k]] -= 1          # 左边滑出窗口
            if win == need:
                res.append(i - k + 1)
        return res

